import{_ as d,C as i,o as t,c as r,a2 as o,b as n,w as a,a as l,E as c,a3 as h}from"./chunks/framework.CZqXuAiL.js";const w=JSON.parse('{"title":"Extension Compatibility — Apple","description":"How the Apple admin theme stays compatible with every other Pterodactyl extension — the runtime nav harvest, the global component reskin, and what extension authors should (and should not) do.","frontmatter":{"title":"Extension Compatibility — Apple","description":"How the Apple admin theme stays compatible with every other Pterodactyl extension — the runtime nav harvest, the global component reskin, and what extension authors should (and should not) do."},"headers":[],"relativePath":"apple/user-guide/compatibility.md","filePath":"apple/user-guide/compatibility.md","lastUpdated":null}'),p={name:"apple/user-guide/compatibility.md"};function m(u,e,b,g,y,k){const s=i("Mermaid");return t(),r("div",null,[e[1]||(e[1]=o('<h1 id="extension-compatibility" tabindex="-1">Extension Compatibility <a class="header-anchor" href="#extension-compatibility" aria-label="Permalink to &quot;Extension Compatibility&quot;">​</a></h1><p>Apple&#39;s design rule is <strong>coexist, never conquer</strong>. Two mechanisms make every other extension work with the theme automatically — no allowlist, no per-extension CSS.</p><h2 id="_1-the-sidebar-is-harvested-not-hardcoded" tabindex="-1">1. The sidebar is harvested, not hardcoded <a class="header-anchor" href="#_1-the-sidebar-is-harvested-not-hardcoded" aria-label="Permalink to &quot;1. The sidebar is harvested, not hardcoded&quot;">​</a></h2><p>Apple never writes its own navigation. On every admin page, <code>sidebar.js</code> reads the panel&#39;s own <code>ul.sidebar-menu</code> — the exact DOM Pterodactyl and every extension already build — and re-renders it as the Apple sidebar:</p>',4)),(t(),n(h,null,{default:a(()=>[c(s,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Pterodactyl%20core%3Cbr%2F%3EOverview%20%C2%B7%20Settings%20%C2%B7%20API%20%E2%80%A6%22%5D%20--%3E%20M%5B%22ul.sidebar-menu%3Cbr%2F%3E(stock%20DOM%2C%20hidden)%22%5D%0A%20%20%20%20B%5B%22Blueprint%3Cbr%2F%3EExtensions%20link%22%5D%20--%3E%20M%0A%20%20%20%20C%5B%22Extension%20A%3Cbr%2F%3Emarker-injected%20link%22%5D%20--%3E%20M%0A%20%20%20%20D%5B%22Extension%20B%3Cbr%2F%3Eservice-provider%20link%22%5D%20--%3E%20M%0A%20%20%20%20M%20--%3E%20H%5B%22sidebar.js%20harvest%3Cbr%2F%3Eheaders%20%C2%B7%20links%20%C2%B7%20icons%20%C2%B7%20active%22%5D%0A%20%20%20%20H%20--%3E%20R%5B%22Apple%20sidebar%3Cbr%2F%3Esections%20%C2%B7%20filter%20%C2%B7%20rail%20%C2%B7%20drawer%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>What gets preserved per item:</p><ul><li><strong>Section headers</strong> (<code>li.header</code>) become Apple section labels, in original order</li><li><strong>Every link</strong> with its <code>href</code>, its Font Awesome icon class, its label and its <strong>server-computed active state</strong></li><li><strong>Any injection style</strong> — Blade marker blocks, <code>@yield(&#39;blueprint.sidenav&#39;)</code>, JS-injected items (including Apple&#39;s own settings link)</li></ul><p>Install, update or remove an extension and the sidebar simply reflects the new reality on the next page load. There is nothing to register with Apple.</p><h2 id="_2-components-are-reskinned-globally" tabindex="-1">2. Components are reskinned globally <a class="header-anchor" href="#_2-components-are-reskinned-globally" aria-label="Permalink to &quot;2. Components are reskinned globally&quot;">​</a></h2><p>Apple restyles the standard AdminLTE 2 / Bootstrap 3 vocabulary that every admin page already outputs. An extension page that renders stock markup looks native with zero changes:</p><table tabindex="0"><thead><tr><th>Component family</th><th>Covered selectors</th></tr></thead><tbody><tr><td>Cards</td><td><code>.box</code> (+ header/body/footer/tools, semantic <code>.box-solid</code> tints)</td></tr><tr><td>Buttons</td><td><code>.btn</code> all variants and sizes, radio <code>btn-group[data-toggle=&quot;buttons&quot;]</code> → iOS segmented control</td></tr><tr><td>Forms</td><td><code>.form-control</code>, labels, input groups, validation states, iCheck</td></tr><tr><td>Tables</td><td><code>.table</code> (hover, striped, bordered, row states), DataTables chrome</td></tr><tr><td>Tabs</td><td><code>.nav-tabs</code> and <code>.nav-tabs-custom</code> → segmented control, <code>.nav-pills</code>, <code>.nav-stacked</code></td></tr><tr><td>Feedback</td><td><code>.alert</code>, <code>.callout</code>, <code>.label</code>, <code>.badge</code>, SweetAlert</td></tr><tr><td>Overlays</td><td><code>.modal-*</code>, <code>.dropdown-menu</code>, tooltips</td></tr><tr><td>Data display</td><td><code>.small-box</code>, <code>.info-box</code>, <code>.description-block</code>, <code>.progress</code></td></tr><tr><td>Misc</td><td>pagination, panels, wells, list groups, select2 (single, multiple, dropdowns)</td></tr></tbody></table><p>Vendor quirks are neutralized deliberately: Pterodactyl&#39;s own <code>pterodactyl.css</code> hardcodes dark box headers, solid <code>!important</code> alert fills, dark modal bodies and a heavy box shadow — Apple overrides each at higher specificity (or matching <code>!important</code>) so both modes stay correct.</p><h2 id="what-extension-authors-should-do" tabindex="-1">What extension authors should do <a class="header-anchor" href="#what-extension-authors-should-do" aria-label="Permalink to &quot;What extension authors should do&quot;">​</a></h2><ul><li><strong>Render stock AdminLTE markup.</strong> <code>.box</code>, <code>.form-control</code>, <code>.btn-*</code>, <code>.table</code> — the theme does the rest.</li><li><strong>Consume the <code>--ap-*</code> custom properties</strong> for anything custom (see the <a href="./../../configuration/reference#css-custom-properties-for-extension-authors">Configuration Reference</a>).</li><li><strong>Register your admin link the usual ways</strong> — Blade marker block or Blueprint sidenav yield. It appears in the Apple sidebar automatically.</li></ul><h2 id="what-to-avoid" tabindex="-1">What to avoid <a class="header-anchor" href="#what-to-avoid" aria-label="Permalink to &quot;What to avoid&quot;">​</a></h2><ul><li><strong>Hardcoded palette hexes</strong> (<code>#1e1e2e</code>, <code>#3c8dbc</code>) — they break the light mode and the admin&#39;s accent choice.</li><li><strong>Injecting your own sidebar/topbar chrome</strong> — two sidebars is worse than none; add a link to the stock menu instead.</li><li><strong><code>!important</code> inline styles</strong> on components Apple already owns — you will fight the theme and lose in one of the modes.</li></ul><h2 id="known-limits" tabindex="-1">Known limits <a class="header-anchor" href="#known-limits" aria-label="Permalink to &quot;Known limits&quot;">​</a></h2><ul><li>Extensions that render <strong>fully custom layouts</strong> (their own nav, own design system) keep their look — Apple never forces itself over custom UI. Blueprint&#39;s own extensions page is an example: its cards keep Blueprint styling inside Apple&#39;s chrome.</li><li>AdminLTE&#39;s push-menu is replaced by Apple&#39;s drawer; the stock toggle is hidden but the stock sidebar DOM stays in place for compatibility.</li></ul>',13))])}const x=d(p,[["render",m]]);export{w as __pageData,x as default};
